result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/lru.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { LRU } from './lru.js';

test('get() refreshes recency so a recently-read key survives eviction', () => {
  const c = new LRU(2);
  c.put(1, 'a');
  c.put(2, 'b');
  c.get(1);          // key 1 is now the most recently used
  c.put(3, 'c');     // capacity exceeded -> must evict key 2, NOT key 1
  assert.equal(c.get(1), 'a', 'key 1 was read last and must survive');
  assert.equal(c.get(3), 'c');
});

test('overwrite updates value AND recency', () => {
  const c = new LRU(2);
  c.put(1, 'a');
  c.put(2, 'b');
  c.put(1, 'a2');    // overwrite: new value + moves key 1 to MRU position
  c.put(3, 'c');     // must evict key 2 (oldest), not the refreshed key 1
  assert.equal(c.get(1), 'a2', 'overwritten value must be visible');
  assert.equal(c.get(2), -1, 'key 2 was least recently used and must be evicted');
  assert.equal(c.get(3), 'c');

  const d = new LRU(2);
  d.put(1, 'a');
  d.put(2, 'b');
  d.put(1, 'a2');    // overwrite makes 1 MRU
  d.put(3, 'c');     // evict 2
  d.put(4, 'd');     // evict 3? no: after evicting 2 order is [1,3], so evict 1... wait: 1 is MRU, so evict 3
  assert.equal(d.get(1), 'a2', 'overwritten key survives a later eviction');
});

test('capacity 1: every insert evicts the previous key', () => {
  const c = new LRU(1);
  c.put(1, 'a');
  assert.equal(c.get(1), 'a');
  c.put(2, 'b');
  assert.equal(c.get(1), -1);
  assert.equal(c.get(2), 'b');
  c.put(2, 'b2');    // overwrite sole slot
  assert.equal(c.get(2), 'b2');
  c.get(2);          // get on sole key must not break anything
  assert.equal(c.get(2), 'b2');
});

test('2000-op seeded fuzz matches reference LRU implementation', () => {
  // Deterministic PRNG (mulberry32) so failures are reproducible.
  let seed = 0xdeadbeef;
  const rand = () => {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  // Reference implementation: Map for values + array for explicit recency order.
  class RefLRU {
    constructor(cap) {
      this.cap = cap;
      this.data = new Map();
      this.order = [];   // front = LRU, back = MRU
    }
    #touch(k) {
      const i = this.order.indexOf(k);
      if (i !== -1) this.order.splice(i, 1);
      this.order.push(k);
    }
    get(k) {
      if (!this.data.has(k)) return -1;
      this.#touch(k);
      return this.data.get(k);
    }
    put(k, v) {
      if (this.data.has(k)) {
        this.data.set(k, v);
        this.#touch(k);          // overwrite refreshes recency too
      } else {
        this.data.set(k, v);
        this.order.push(k);
      }
      if (this.order.length > this.cap) {
        const evicted = this.order.shift();
        this.data.delete(evicted);
      }
    }
  }

  const real = new LRU(7);
  const ref = new RefLRU(7);

  for (let op = 0; op < 2000; op++) {
    const k = Math.floor(rand() * 12);   // keys 0..11 > cap 7 forces churn
    if (rand() < 0.6) {
      const v = `v${op}`;
      real.put(k, v);
      ref.put(k, v);
    } else {
      const rReal = real.get(k);
      const rRef = ref.get(k);
      assert.equal(rReal, rRef,
        `op ${op}: get(${k}) returned ${rReal}, reference says ${rRef}`);
    }
    // Spot-check full agreement every 100 ops and at the end.
    if (op % 100 === 99 || op === 1999) {
      for (let probe = 0; probe < 12; probe++) {
        assert.equal(real.get(probe), ref.get(probe),
          `op ${op}: divergence on probe ${probe}`);
      }
    }
  }
});
"})
